"""Wave-2 built-in locale fallback (Goal PDW2-D-UX-STUDENT).

The Wave-2 studio is delivered as an additive module family, so its
strings live here instead of the shared locale JSON files (which are
owned by the frozen student UI and only change at integration).
``wt`` prefers the application locale and falls back to this built-in
table, so existing app strings keep their translations and Wave-2
strings are available in English and Chinese from day one.
"""

from __future__ import annotations

from app.ui import locale as _app_locale
from app.ui.locale import t


