_original_load_locale = _app_locale.load_locale


def _merged_locale(lang: str) -> dict:
    """Application locale merged with the Wave-2 built-in strings.

    Registered at import of this module so the shared UI components
    (which translate through ``app.ui.locale.t``) resolve Wave-2 keys
    without changing the frozen locale JSON files. Existing keys are
    never overridden; INT may fold these strings into the locale files
    at integration.
    """
    base = dict(_original_load_locale(lang))
    base.update(_BUILTIN.get(lang) or _BUILTIN["en"])
    return base


# Additive runtime registration (see _merged_locale docstring).
_app_locale.load_locale = _merged_locale


def wt(key: str, lang: str = "en", **fmt) -> str:
    """Wave-2 locale lookup (resolves through the merged locale)."""
    return t(key, lang, **fmt)


__all__ = ["wt"]
